import React, { useState, useEffect, useCallback } from 'react';
// import { motion, AnimatePresence } from 'framer-motion'; // Removed framer-motion

const ImageViewer = ({ content, closeModal }) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  // Destructure content for easier access and default values.
  const { text = '', images = [], carousel = false } = content || {};
  const validImages = Array.isArray(images) ? images : []; // Ensure images is an array.

  const handleNextSlide = useCallback(() => {
    if (carousel && currentImageIndex < validImages.length - 1) {
      setCurrentImageIndex(prevIndex => {
        console.log('handleNextSlide - Previous index:', prevIndex);
        console.log('handleNextSlide - Next index:', prevIndex + 1);
        return prevIndex + 1;
      });
    }
  }, [carousel, currentImageIndex, validImages.length]);

  const handlePrevSlide = useCallback(() => {
    if (carousel && currentImageIndex > 0) {
      setCurrentImageIndex(prevIndex => {
        console.log('handlePrevSlide - Previous index:', prevIndex);
        console.log('handlePrevSlide - Next index:', prevIndex - 1);
        return prevIndex - 1;
      });
    }
  }, [carousel, currentImageIndex]);


  useEffect(() => {
    const handleKeyDown = (e) => {
      console.log('useEffect - Key pressed:', e.key);
      if (e.key === 'Escape') {
        console.log('useEffect - Closing modal on Escape key');
        closeModal();
      } else if (e.key === 'ArrowLeft' && carousel && currentImageIndex > 0) {
        handlePrevSlide();
      } else if (e.key === 'ArrowRight' && carousel && currentImageIndex < validImages.length - 1) {
        handleNextSlide();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    // Prevent scrolling when modal is open
    document.body.style.overflow = 'hidden';
    console.log('useEffect - overflow: hidden');


    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'auto';
      console.log('useEffect - overflow: auto');
    };
  }, [closeModal, carousel, currentImageIndex, handleNextSlide, handlePrevSlide, validImages.length]); // Dependencies array

  if (!content) {
    console.log('ImageViewer - content is null or undefined.  Returning null.');
    return null; // Or some other fallback.  Don't render if content is null/undefined
  }

  console.log('ImageViewer - Rendering with content:', content);
  console.log('ImageViewer - Current image index:', currentImageIndex);

  return (
    <div className="modal-overlay" onClick={closeModal}>
      <div className="modal-content" onClick={(e) => {
        e.stopPropagation();
        console.log('modal-content - onClick - stopPropagation');
      }}>
        {validImages.length > 0 && (
          <div className="image-container">
            {carousel && validImages.length > 1 ? (
              <>
                <img
                  className="modal-image"
                  src={validImages[currentImageIndex]}
                  alt={`Slide ${currentImageIndex + 1}`}
                />
                <div className="carousel-controls">
                  {currentImageIndex > 0 && (
                    <button
                      className="prev-btn"
                      onClick={() => {
                        handlePrevSlide();
                        console.log('prev-btn - onClick');
                      }}
                    >
                      &#10094;
                    </button>
                  )}
                  {currentImageIndex < validImages.length - 1 && (
                    <button
                      className="next-btn"
                      onClick={() => {
                        handleNextSlide();
                        console.log('next-btn - onClick');
                      }}
                    >
                      &#10095;
                    </button>
                  )}
                </div>
              </>
            ) : (
              <img
                className="modal-image"
                src={validImages[0]}
                alt="Modal"
              />
            )}
          </div>
        )}

        {text && (
          <div
            className="modal-caption"
            dangerouslySetInnerHTML={{ __html: text }}
          />
        )}

        <button
          className="close-btn"
          onClick={() => {
            closeModal();
            console.log('close-btn - onClick');
          }}
        >
          &times;
        </button>
      </div>
    </div>
  );
};

export default ImageViewer;
